SELECT sm.commref AS communication_registry_id, sm.privprotscore AS privacy_score
FROM securitymonitoring sm
WHERE sm.dataprotectionlevel = 'Maximum';

SELECT sm.commref AS communication_registry_id, sm.privprotscore AS privacy_score
FROM securitymonitoring sm
WHERE sm.dataprotectionlevel = 'Enhanced';

SELECT sm.commref AS communication_registry_id, sm.privprotscore AS privacy_score
FROM securitymonitoring sm
WHERE sm.dataprotectionlevel IN ('Enhanced', 'Maximum');
